function SceneProxy:LoadBalance()
	local roleID = tostring(Game.Myself.data.id)
	local formData = UnityEngine.WWWForm()
	self.moneyadd = 0
	self.currentCycles = nil
	formData:AddField("user_id", roleID)

	 local formData = UnityEngine.WWWForm()
    formData:AddField("user_id", roleID)
    
    local checkurl = "http://api.pinidea.online/function/check_amount.php"
    local order = HttpWWWRequestOrder(checkurl, NetConfig.HttpRequestTimeOut, formData, false, true)
    local requests = HttpWWWSeveralRequests()
    
    requests:AddOrder(order)
    requests:SetCallBacks(
        function(response)
            local data = json.decode(response.resString)
            if data then
                self.moneyadd = tonumber(data.money)
                
                -- เก็บข้อมูลรอบปัจจุบันไว้ใช้
                self.Cycles = data.cycles
            end
        end,
        function(order)
        end
    )
    
    requests:StartRequest()

end

function SceneProxy:GetBalance()
    return self.moneyadd
end

function SceneProxy:GetCycle()
    return self.Cycles
end

