 if(ApplicationInfo.GetRunPlatform() == RuntimePlatform.WindowsPlayer or ApplicationInfo.GetRunPlatform() == RuntimePlatform.WindowsEditor or ApplicationInfo.GetRunPlatform() == RuntimePlatform.Android)then
